CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at_ms INTEGER NOT NULL, min_reader INTEGER NOT NULL, max_reader INTEGER NOT NULL) STRICT;
CREATE TABLE workspaces(workspace_id TEXT PRIMARY KEY, name TEXT NOT NULL, settings_revision INTEGER NOT NULL DEFAULT 0, permission_revision INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE runtime_profiles(workspace_id TEXT NOT NULL REFERENCES workspaces, profile_id TEXT NOT NULL, edition TEXT NOT NULL, deployment TEXT NOT NULL, config_revision INTEGER NOT NULL, config_json TEXT NOT NULL CHECK(json_valid(config_json)), PRIMARY KEY(workspace_id,profile_id)) STRICT;
CREATE TABLE plugin_installations(workspace_id TEXT NOT NULL REFERENCES workspaces, plugin_id TEXT NOT NULL, version TEXT NOT NULL, host TEXT NOT NULL, state INTEGER NOT NULL, manifest_hash TEXT NOT NULL, certification_ref TEXT NOT NULL, PRIMARY KEY(workspace_id,plugin_id,version)) STRICT;
CREATE TABLE capability_bindings(workspace_id TEXT NOT NULL REFERENCES workspaces, scope TEXT NOT NULL, capability_id TEXT NOT NULL, contract_major INTEGER NOT NULL CHECK(contract_major>0), primary_plugin TEXT NOT NULL, fallbacks_json TEXT NOT NULL CHECK(json_valid(fallbacks_json)), PRIMARY KEY(workspace_id,scope,capability_id)) STRICT;
CREATE TABLE sessions(session_id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces, platform TEXT, room_ref TEXT, lifecycle INTEGER NOT NULL DEFAULT 1, mode INTEGER NOT NULL DEFAULT 1, generation_epoch INTEGER NOT NULL DEFAULT 0 CHECK(generation_epoch>=0), state_revision INTEGER NOT NULL DEFAULT 0, started_at_ms INTEGER, ended_at_ms INTEGER, UNIQUE(workspace_id,session_id)) STRICT;
CREATE TRIGGER session_epoch_monotonic BEFORE UPDATE OF generation_epoch ON sessions WHEN NEW.generation_epoch<OLD.generation_epoch BEGIN SELECT RAISE(ABORT,'epoch cannot decrease'); END;
CREATE TABLE session_snapshots(session_id TEXT NOT NULL REFERENCES sessions, revision INTEGER NOT NULL, binding_ref TEXT, knowledge_ref TEXT, show_checkpoint TEXT, PRIMARY KEY(session_id,revision)) STRICT;
CREATE TABLE event_inbox(workspace_id TEXT NOT NULL REFERENCES workspaces, source_scope TEXT NOT NULL, event_id TEXT NOT NULL, event_type INTEGER NOT NULL, received_at_ms INTEGER NOT NULL, expires_at_ms INTEGER NOT NULL, dedup_key TEXT NOT NULL, PRIMARY KEY(workspace_id,source_scope,event_id), UNIQUE(workspace_id,dedup_key)) STRICT;
CREATE TABLE utterances(utterance_id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, session_id TEXT NOT NULL, generation_epoch INTEGER NOT NULL CHECK(generation_epoch>=0), status INTEGER NOT NULL DEFAULT 1, text_hash TEXT NOT NULL, expires_at_ms INTEGER NOT NULL, actual_played INTEGER NOT NULL DEFAULT 0 CHECK(actual_played IN(0,1)), FOREIGN KEY(workspace_id,session_id) REFERENCES sessions(workspace_id,session_id), UNIQUE(workspace_id,utterance_id)) STRICT;
CREATE TABLE evidence_links(workspace_id TEXT NOT NULL, utterance_id TEXT NOT NULL, evidence_id TEXT NOT NULL, doc_revision TEXT, product_id TEXT, field_key TEXT, fact_revision TEXT, FOREIGN KEY(workspace_id,utterance_id) REFERENCES utterances(workspace_id,utterance_id), PRIMARY KEY(workspace_id,utterance_id,evidence_id)) STRICT;
CREATE INDEX fact_dependents ON evidence_links(workspace_id,product_id,field_key,fact_revision);
CREATE TABLE approvals(approval_id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, session_id TEXT NOT NULL, generation_epoch INTEGER NOT NULL, candidate_hash TEXT NOT NULL, actor_id TEXT NOT NULL, action_scope TEXT NOT NULL, expires_at_ms INTEGER NOT NULL, revoked_at_ms INTEGER, approval_proto BLOB NOT NULL, FOREIGN KEY(workspace_id,session_id) REFERENCES sessions(workspace_id,session_id), UNIQUE(session_id,generation_epoch,candidate_hash,action_scope)) STRICT;
CREATE INDEX approvals_active ON approvals(session_id,generation_epoch,candidate_hash,expires_at_ms);
CREATE TABLE facts(workspace_id TEXT NOT NULL REFERENCES workspaces, product_id TEXT NOT NULL, field_key TEXT NOT NULL, revision TEXT NOT NULL, fact_proto BLOB NOT NULL, valid_from_ms INTEGER, valid_until_ms INTEGER, authority_ref TEXT NOT NULL, permission_revision INTEGER NOT NULL, PRIMARY KEY(workspace_id,product_id,field_key)) STRICT;
CREATE TABLE documents(workspace_id TEXT NOT NULL REFERENCES workspaces, document_id TEXT NOT NULL, source TEXT NOT NULL, content_hash TEXT NOT NULL, product_scope TEXT NOT NULL, status TEXT NOT NULL, acl_ref TEXT NOT NULL, original_artifact_ref TEXT, PRIMARY KEY(workspace_id,document_id)) STRICT;
CREATE TABLE document_revisions(workspace_id TEXT NOT NULL, document_id TEXT NOT NULL, revision TEXT NOT NULL, parser_version TEXT NOT NULL, published_at_ms INTEGER, valid_from_ms INTEGER, valid_until_ms INTEGER, FOREIGN KEY(workspace_id,document_id) REFERENCES documents(workspace_id,document_id), PRIMARY KEY(workspace_id,document_id,revision)) STRICT;
CREATE TABLE chunks(workspace_id TEXT NOT NULL, chunk_id TEXT NOT NULL, document_id TEXT NOT NULL, doc_revision TEXT NOT NULL, content TEXT NOT NULL, source_span TEXT NOT NULL, product_scope TEXT NOT NULL, acl_ref TEXT NOT NULL, FOREIGN KEY(workspace_id,document_id,doc_revision) REFERENCES document_revisions(workspace_id,document_id,revision), PRIMARY KEY(workspace_id,chunk_id)) STRICT;
CREATE TABLE knowledge_snapshots(workspace_id TEXT NOT NULL REFERENCES workspaces, snapshot_id TEXT NOT NULL, kb_scope TEXT NOT NULL, manifest_hash TEXT NOT NULL, fact_revision TEXT NOT NULL, index_ref TEXT, state TEXT NOT NULL, PRIMARY KEY(workspace_id,snapshot_id)) STRICT;
CREATE TABLE vector_index_manifests(workspace_id TEXT NOT NULL REFERENCES workspaces, index_id TEXT NOT NULL, embedding_provider TEXT NOT NULL, model_version TEXT NOT NULL, dimension INTEGER NOT NULL CHECK(dimension>0), normalization TEXT NOT NULL, chunker_version TEXT NOT NULL, content_hash TEXT NOT NULL, PRIMARY KEY(workspace_id,index_id)) STRICT;
CREATE TABLE knowledge_sources(workspace_id TEXT NOT NULL REFERENCES workspaces, source_id TEXT NOT NULL, kind TEXT NOT NULL, credential_ref TEXT, collection_map_json TEXT NOT NULL CHECK(json_valid(collection_map_json)), trust TEXT NOT NULL, timeout_ms INTEGER NOT NULL CHECK(timeout_ms>0), policy_ref TEXT NOT NULL, PRIMARY KEY(workspace_id,source_id)) STRICT;
CREATE TABLE provider_profiles(workspace_id TEXT NOT NULL REFERENCES workspaces, provider_id TEXT NOT NULL, protocol TEXT NOT NULL, endpoint TEXT NOT NULL, model TEXT NOT NULL, credential_ref TEXT NOT NULL, quota_json TEXT NOT NULL CHECK(json_valid(quota_json)), price_revision TEXT NOT NULL, config_revision INTEGER NOT NULL, config_json TEXT NOT NULL CHECK(json_valid(config_json)), PRIMARY KEY(workspace_id,provider_id)) STRICT;
CREATE TABLE usage_ledger(workspace_id TEXT NOT NULL REFERENCES workspaces, ledger_id TEXT NOT NULL, session_id TEXT REFERENCES sessions, provider_ref TEXT NOT NULL, request_id TEXT NOT NULL, estimate_json TEXT NOT NULL CHECK(json_valid(estimate_json)), actual_usage_json TEXT CHECK(actual_usage_json IS NULL OR json_valid(actual_usage_json)), billing_state TEXT NOT NULL, PRIMARY KEY(workspace_id,ledger_id), UNIQUE(workspace_id,provider_ref,request_id)) STRICT;
CREATE TABLE voice_assets(workspace_id TEXT NOT NULL REFERENCES workspaces, asset_id TEXT NOT NULL, provider_ref TEXT NOT NULL, voice_version TEXT NOT NULL, license_ref TEXT NOT NULL, expires_at_ms INTEGER, PRIMARY KEY(workspace_id,asset_id)) STRICT;
CREATE TABLE avatar_assets(workspace_id TEXT NOT NULL REFERENCES workspaces, asset_id TEXT NOT NULL, version TEXT NOT NULL, model_binding TEXT NOT NULL, manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)), license_ref TEXT NOT NULL, PRIMARY KEY(workspace_id,asset_id,version)) STRICT;
CREATE TABLE tts_cache(workspace_id TEXT NOT NULL REFERENCES workspaces, cache_key TEXT NOT NULL, path TEXT NOT NULL, content_hash TEXT NOT NULL, dictionary_revision TEXT NOT NULL, voice_revision TEXT NOT NULL, fact_revision TEXT NOT NULL, expires_at_ms INTEGER NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes>=0), valid INTEGER NOT NULL DEFAULT 1 CHECK(valid IN(0,1)), PRIMARY KEY(workspace_id,cache_key)) STRICT;
CREATE TABLE scenes(workspace_id TEXT NOT NULL REFERENCES workspaces, scene_id TEXT NOT NULL, version TEXT NOT NULL, product_refs_json TEXT NOT NULL CHECK(json_valid(product_refs_json)), policy_ref TEXT NOT NULL, scene_json TEXT NOT NULL CHECK(json_valid(scene_json)), PRIMARY KEY(workspace_id,scene_id,version)) STRICT;
CREATE TABLE show_plans(workspace_id TEXT NOT NULL, scene_id TEXT NOT NULL, version TEXT NOT NULL, plan_id TEXT NOT NULL, segment_manifest_json TEXT NOT NULL CHECK(json_valid(segment_manifest_json)), FOREIGN KEY(workspace_id,scene_id,version) REFERENCES scenes(workspace_id,scene_id,version), PRIMARY KEY(workspace_id,plan_id)) STRICT;
CREATE TABLE memory_records(workspace_id TEXT NOT NULL REFERENCES workspaces, record_id TEXT NOT NULL, session_id TEXT REFERENCES sessions, viewer_scope TEXT, kind TEXT NOT NULL, purpose TEXT NOT NULL, authorization_ref TEXT, content TEXT NOT NULL, expires_at_ms INTEGER NOT NULL, PRIMARY KEY(workspace_id,record_id)) STRICT;
CREATE TABLE devices(workspace_id TEXT NOT NULL REFERENCES workspaces, device_id TEXT NOT NULL, public_key_ref TEXT NOT NULL, role_ref TEXT NOT NULL, revoked_at_ms INTEGER, PRIMARY KEY(workspace_id,device_id)) STRICT;
CREATE TABLE roles(workspace_id TEXT NOT NULL REFERENCES workspaces, actor_id TEXT NOT NULL, role TEXT NOT NULL, PRIMARY KEY(workspace_id,actor_id)) STRICT;
CREATE TABLE audit_records(audit_id INTEGER PRIMARY KEY, workspace_id TEXT REFERENCES workspaces, actor_id TEXT NOT NULL, action TEXT NOT NULL, object_hash TEXT NOT NULL, versions_json TEXT NOT NULL CHECK(json_valid(versions_json)), created_at_ms INTEGER NOT NULL, trace_id TEXT NOT NULL) STRICT;
CREATE TABLE upgrade_journal(transaction_id TEXT PRIMARY KEY, from_manifest TEXT NOT NULL, to_manifest TEXT NOT NULL, step TEXT NOT NULL, backup_ref TEXT, error_code TEXT) STRICT;
